require 'sendgrid-ruby'

# Description: Sublayer::Action responsible for sending an email via SendGrid.
# It takes parameters like sender email, recipient email, subject, and body (plain text or HTML).
# Useful for sending notifications, summaries, or reports generated by AI workflows.
#
# Requires: 'sendgrid-ruby' gem
# $ gem install sendgrid-ruby
# Or add `gem 'sendgrid-ruby'` to your Gemfile
#
# It is initialized with sender_email, recipient_email, subject, and content (text or html).
# It returns the HTTP status code to confirm the message was sent successfully.
#
# Example usage: When you want to send a notification or update from an AI process via email.

class SendgridSendEmailAction < Sublayer::Actions::Base
  def initialize(sender_email:, recipient_email:, subject:, content:, content_type: 'text/plain')
    @sender_email = sender_email
    @recipient_email = recipient_email
    @subject = subject
    @content = content
    @content_type = content_type # text/plain or text/html
    @sendgrid_api_key = ENV['SENDGRID_API_KEY']
  end

  def call
    from = SendGrid::Email.new(email: @sender_email)
    to = SendGrid::Email.new(email: @recipient_email)
    content = SendGrid::Content.new(type: @content_type, value: @content)
    mail = SendGrid::Mail.new(from, @subject, to, content)

    sg = SendGrid::API.new(api_key: @sendgrid_api_key)
    response = sg.client.mail._('send').post(request_body: mail.to_json)

    if response.status_code.to_i >= 200 && response.status_code.to_i < 300
      Sublayer.configuration.logger.log(:info, "Email sent successfully to #{@recipient_email}")
      response.status_code.to_i
    else
      error_message = "Failed to send email to #{@recipient_email}. HTTP Response Code: #{response.status_code}, Body: #{response.body}"
      Sublayer.configuration.logger.log(:error, error_message)
      raise StandardError, error_message
    end
  rescue StandardError => e
    Sublayer.configuration.logger.log(:error, "Error sending email: #{e.message}")
    raise e
  end
end
